        # Handle NaN or non-string values
        if not isinstance(text, str):
            return text

        # Split into words
        words = text.split()

        # Find matching words and their indices
        matching_indices = []
        matching_words = []

        for i, word in enumerate(words):
            if re.search(pattern, word):
                matching_indices.append(i)
