        # Reverse the matching words
        matching_words.reverse()

        # Put reversed words back
        for i, idx in enumerate(matching_indices):
            words[idx] = matching_words[i]

        return ' '.join(words)

    # Create a copy of the DataFrame
    result = df.copy()

    # Apply the helper function to the specified column
    result[column_name] = result[column_name].apply(reverse_matching_words)

    return result

